package io.github.jesterportfolio.hearth.survival.economy;
import io.github.jesterportfolio.hearth.inventory.InventoryPayload;
import io.github.jesterportfolio.hearth.persistence.StorageFailure;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
final class NativeTransactionsTest {
 @TempDir Path root;NativeTradeJournal journal;NativeTransactions core;final UUID group=UUID.randomUUID(),request=UUID.randomUUID();final AtomicLong clock=new AtomicLong();final ArrayDeque<Runnable> owner=new ArrayDeque<>();final CompletableFuture<NativeTransactions.Result> database=new CompletableFuture<>();BooleanSupplier valid;final Port first=new Port(),second=new Port();
 static InventoryPayload payload(String s){var bytes=new byte[41][];if(s!=null)bytes[0]=s.getBytes(java.nio.charset.StandardCharsets.UTF_8);return InventoryPayload.pack(bytes);}
 static final class Port implements NativeTransactions.Port{final UUID id=UUID.randomUUID();InventoryPayload payload=NativeTransactionsTest.payload("native existing items");boolean current=true,frozen,failSave,failValidate,failCapture;int saves,applies;final List<String> notices=new ArrayList<>();public UUID player(){return id;}public boolean current(){return current;}public InventoryPayload capture(){if(failCapture)throw new IllegalStateException("CURSOR");return payload;}public boolean same(InventoryPayload before){return payload.equals(before);}public void freeze(boolean b){frozen=b;}public void saveNative(){saves++;if(failSave)throw new IllegalStateException();}public void validate(InventoryPayload p){if(failValidate)throw new IllegalArgumentException();}public void apply(InventoryPayload p){payload=p;applies++;}public void notice(String code){notices.add(code);}}
 @BeforeEach void setup()throws Exception{journal=new NativeTradeJournal(root,group);core=new NativeTransactions(journal,owner::add,clock::get);}
 void pump(){while(!owner.isEmpty())owner.remove().run();}
 CompletionStage<NativeTransactions.Result> begin(boolean peer){return core.begin(request,peer?"PEER":"SHOP",peer?List.of(first,second):List.of(first),(before,fence)->{valid=fence;return database;});}
 NativeTransactions.Result result(boolean peer,boolean replay){return new NativeTransactions.Result(peer?Map.of(first.id,payload("a after"),second.id,payload("b after")):Map.of(first.id,payload("a after")),"receipt",replay);}
 @Test void source_native_save_and_marker_precede_database_and_apply_waits_for_owner()throws Exception{var future=begin(false);assertTrue(first.frozen);assertEquals(1,first.saves);assertTrue(journal.held(first.id));assertTrue(valid.getAsBoolean());database.complete(result(false,false));assertEquals(0,first.applies);pump();assertEquals(payload("a after"),first.payload);assertEquals(2,first.saves);assertFalse(first.frozen);assertFalse(journal.held(first.id));assertFalse(core.busy(first.id));assertNotNull(future.toCompletableFuture().join());}
 @Test void both_native_payloads_are_validated_before_either_peer_inventory_is_changed(){begin(true);second.failValidate=true;database.complete(result(true,false));pump();assertEquals(0,first.applies);assertEquals(0,second.applies);assertTrue(journal.held(first.id));assertTrue(journal.held(second.id));}
 @Test void known_refusal_preserves_items_and_releases_only_same_live_participant(){var before=first.payload;var future=begin(false);database.completeExceptionally(new StorageFailure("economy","ECON_QUOTE_CHANGED"));pump();assertEquals(before,first.payload);assertFalse(first.frozen);assertFalse(journal.held(first.id));assertTrue(future.toCompletableFuture().isCompletedExceptionally());}
 @Test void synchronous_capacity_refusal_is_also_safe_without_permanent_hold(){core.begin(request,"SHOP",List.of(first),(before,fence)->{throw new StorageFailure("economy","ECON_ITEMS");});assertFalse(first.frozen);assertTrue(journal.pending().isEmpty());}
 @Test void unknown_commit_and_duplicate_receipt_are_never_reapplied_or_automatically_cleared(){begin(false);database.completeExceptionally(new StorageFailure("economy","COMMIT_UNKNOWN"));pump();assertEquals(0,first.applies);assertTrue(first.frozen);assertTrue(journal.held(first.id));assertFalse(valid.getAsBoolean());}
 @Test void receipt_replay_is_for_inspection_and_does_not_grant_items_again(){begin(false);database.complete(result(false,true));pump();assertEquals(0,first.applies);assertTrue(journal.held(first.id));}
 @Test void death_or_disconnect_revokes_worker_fence_and_late_result_cannot_touch_replacement(){begin(true);core.invalidate(first.id);first.current=false;database.complete(result(true,false));pump();assertFalse(valid.getAsBoolean());assertEquals(0,first.applies);assertEquals(0,second.applies);assertTrue(second.frozen);assertTrue(journal.held(second.id));}
 @Test void unexpected_live_inventory_mutation_is_preserved_without_old_snapshot_overwrite(){begin(false);first.payload=payload("changed by native event");database.complete(result(false,false));pump();assertEquals(payload("changed by native event"),first.payload);assertEquals(0,first.applies);assertTrue(first.frozen);}
 @Test void timeout_prevents_late_success_and_remains_unsettled_until_worker_returns(){begin(false);clock.set(30000);core.tick();assertFalse(valid.getAsBoolean());assertFalse(core.settled());database.complete(result(false,false));pump();assertEquals(0,first.applies);assertTrue(core.settled());assertTrue(journal.held(first.id));}
 @Test void failed_native_save_cannot_run_database_or_publish_success(){first.failSave=true;final boolean[] ran={false};core.begin(request,"SHOP",List.of(first),(before,fence)->{ran[0]=true;return database;});assertFalse(ran[0]);assertTrue(first.frozen);assertTrue(journal.held(first.id));}
 @Test void failed_native_save_after_apply_keeps_receipt_marker_for_manual_review(){begin(false);first.failSave=true;database.complete(result(false,false));pump();assertEquals(1,first.applies);assertTrue(first.frozen);assertTrue(journal.held(first.id));}
 @Test void duplicate_click_cannot_submit_second_operation_or_freeze_another_player(){begin(false);boolean[] ran={false};var next=core.begin(UUID.randomUUID(),"SHOP",List.of(first),(before,fence)->{ran[0]=true;return database;});assertFalse(ran[0]);assertTrue(next.toCompletableFuture().isCompletedExceptionally());assertEquals(1,journal.pending().size());}
 @Test void restart_reads_existing_hold_without_deleting_or_reissuing()throws Exception{begin(true);var restored=new NativeTradeJournal(root,group);assertTrue(restored.held(first.id));assertTrue(restored.held(second.id));assertEquals(request,restored.pending().getFirst().request());assertThrows(Exception.class,()->restored.acquire(new NativeTradeJournal.Pending(UUID.randomUUID(),"SHOP",List.of(first.id))));assertThrows(Exception.class,()->new NativeTradeJournal(root,UUID.randomUUID()));assertEquals(0,first.applies);}
 @Test void unprepared_cursor_is_a_definite_refusal_before_any_marker_or_database(){first.failCapture=true;var result=begin(false);assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertNull(valid);assertTrue(journal.pending().isEmpty());assertFalse(first.frozen);assertEquals(0,first.saves);}
 @Test void malformed_marker_or_symlink_directory_is_not_adopted()throws Exception{Files.writeString(root.resolve("native-economy-pending/bad.pending"),"bad");assertThrows(Exception.class,()->new NativeTradeJournal(root,group));}
}
